<header class="admin-page-head"><div><p class="admin-eyebrow">Team / access</p><h1>Roles</h1><p class="admin-lede">Permission sets for the Raspina operations console.</p></div><a class="admin-primary-button" href="<?= e(admin_url('/roles/new')) ?>">Create role <span aria-hidden="true">-&gt;</span></a></header>
<?php if (!empty($admin_error)): ?><div class="admin-alert error" role="alert"><?= e($admin_error) ?></div><?php endif; ?><section class="admin-panel admin-table-panel"><div class="table-toolbar"><div><p class="admin-eyebrow">Access map</p><h2>Roles and permissions</h2></div><span class="toolbar-meta"><?= count((array) $roles) ?> roles</span></div><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Role</th><th>Kind</th><th>Users</th><th>Permissions</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><?php foreach ((array) $roles as $role): ?><tr><td class="table-primary" data-label="Role"><a href="<?= e(admin_url('/roles/edit/' . (int) $role['id'])) ?>"><?= e($role['title']) ?></a><small><?= e($role['description']) ?></small></td><td data-label="Kind"><?= !empty($role['is_system']) ? 'System' : 'Custom' ?></td><td data-label="Users"><span class="count-badge"><?= (int) $role['user_count'] ?></span></td><td data-label="Permissions"><?= (int) $role['permission_count'] ?> grants</td><td data-label="Actions"><div class="table-actions"><a class="icon-action" href="<?= e(admin_url('/roles/edit/' . (int) $role['id'])) ?>">Edit</a><?php if (empty($role['is_system'])): ?><form method="post" action="<?= e(admin_url('/roles')) ?>" data-confirm="Delete this custom role?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="delete_role"><input type="hidden" name="id" value="<?= (int) $role['id'] ?>"><button class="icon-action danger" type="submit">Delete</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$roles): ?><div class="empty-state"><div><strong>No roles found</strong><p>Import the team access migration, then reload this page.</p></div></div><?php endif; ?></section>
